try {
    let w;
    if (msg.topic === "scroll-cached") {
        w = flow.get("device.weather");
        if (!weatherFresh(w)) {
            node.status({fill:"yellow",shape:"ring",text:"Waiting for fresh Glasgow weather"});
            return null;
